# name: lag1_response_dependence
# description: P(yes | previous consecutive trial yes) minus P(yes | previous trial no), using rows where trial_index increments by 1 from the previous row; observed above the replicate mean means people perseverate on their prior response (sequential dependence the independent-trial model lacks).
def test_statistic(df):
    ti = df["trial_index"].to_numpy().astype(int)
    r = df["rating"].to_numpy().astype(float)
    if len(r) < 3:
        return 0.0
    ok = ti[1:] == ti[:-1] + 1
    prev, cur = r[:-1][ok], r[1:][ok]
    if (prev == 1).sum() == 0 or (prev == 0).sum() == 0:
        return 0.0
    return float(cur[prev == 1].mean() - cur[prev == 0].mean())

# name: late_minus_early_yes_rate
# description: Yes rate on trials in the second half of the session (trial_index >= median) minus the first half; nonzero observed vs a near-zero replicate mean means response bias drifts over the session (positive = growing yes-bias), which the stationary model cannot produce.
def test_statistic(df):
    ti = df["trial_index"].to_numpy().astype(float)
    r = df["rating"].to_numpy().astype(float)
    med = np.median(ti)
    late = ti >= med
    if late.sum() == 0 or (~late).sum() == 0:
        return 0.0
    return float(r[late].mean() - r[~late].mean())

# name: example_target_yes_rate
# description: Yes rate on trials whose target is one of the shown examples; observed below the replicate mean means the model's guessing ceiling is too high (people reject examples more), above means people endorse examples more than the lapse allows.
def test_statistic(df):
    ex = df["number_set"].astype(str).str.split(",", expand=True).apply(pd.to_numeric, errors="coerce")
    t = df["target"].astype(int).to_numpy()[:, None]
    m = (ex.to_numpy() == t).any(axis=1)
    if m.sum() == 0:
        return 0.0
    return float(df["rating"].to_numpy()[m].mean())
